<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
class PurchaseOrder extends Model { use HasUuids; protected $fillable = ['tenant_id', 'company_id', 'branch_id', 'warehouse_id', 'currency_id', 'exchange_rate', 'base_total', 'subtotal', 'discount_total', 'tax_total', 'shipping_total', 'grand_total', 'supplier_id', 'created_by', 'quotation_id', 'number', 'state', 'order_date', 'expected_at', 'supplier_reference', 'payment_terms', 'delivery_address', 'notes']; protected function casts(): array { return ['order_date' => 'date', 'expected_at' => 'date', 'exchange_rate' => 'decimal:12', 'base_total' => 'decimal:6', 'subtotal' => 'decimal:6', 'discount_total' => 'decimal:6', 'tax_total' => 'decimal:6', 'shipping_total' => 'decimal:6', 'grand_total' => 'decimal:6']; } public function items() { return $this->hasMany(PurchaseOrderItem::class); } public function supplier() { return $this->belongsTo(Supplier::class); } public function company() { return $this->belongsTo(Company::class); } public function branch() { return $this->belongsTo(Branch::class); } public function warehouse() { return $this->belongsTo(Warehouse::class); } public function currency() { return $this->belongsTo(AccountingCurrency::class, 'currency_id'); } public function approvals() { return $this->hasMany(ProcurementApproval::class, 'document_id')->where('document_type', self::class); } }
